# frozen_string_literal: true
RSpec.describe TimekeepingRules::EntryRules, ".agent_owner" do
  # "it still commits any positive agent_id without checking that the agent
  # exists and belongs to the entry's company and user (design rule S7)."
  it "answers not_found for an unknown agent, another user's agent, an empty list or a String id" do
    company_agents = { 7 => 1, 8 => 2 }

    expect(described_class.agent_owner(agent_id: 99, user_id: 1, company_agents:)).to eq(:not_found)
    expect(described_class.agent_owner(agent_id: 8, user_id: 1, company_agents:)).to eq(:not_found)
    expect(described_class.agent_owner(agent_id: 7, user_id: 1, company_agents: {})).to eq(:not_found)
    expect(described_class.agent_owner(agent_id: "7", user_id: 1, company_agents:)).to eq(:not_found)
    expect(company_agents).to eq({ 7 => 1, 8 => 2 })
  end
end
